-- Create radical table (assumes level table already exists)
DROP TABLE IF EXISTS `radical`;

CREATE TABLE `radical` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `hanzi` VARCHAR(10) NOT NULL,
  `traditional` VARCHAR(10),
  `pinyin` VARCHAR(50),
  `radical` VARCHAR(50),
  `stroke_count` INT,
  `frequency_rank` INT,
  `general_standard` VARCHAR(20),
  `level_id` INT,
  `meaning` TEXT,
  `meaning_vi` TEXT,
  `meaning_cn` TEXT,
  `meaning_en` TEXT,
  `meaning_jp` TEXT,
  `meaning_kr` TEXT,
  `meaning_th` TEXT,
  `meaning_de` TEXT,
  `meaning_fr` TEXT,
  `meaning_es` TEXT,
  `meaning_it` TEXT,
  `meaning_br` TEXT,
  `meaning_tr` TEXT,
  `is_favorite` TINYINT(1) DEFAULT 0,
  INDEX `idx_hanzi` (`hanzi`),
  INDEX `idx_level_id` (`level_id`),
  INDEX `idx_frequency_rank` (`frequency_rank`),
  FOREIGN KEY (`level_id`) REFERENCES `level`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

